package dev.homecontrol.app;
import android.content.Context;
import android.os.Bundle;
import android.media.*;
import android.graphics.*;
import android.net.Uri;
import org.json.*;
import java.nio.*;

/** Generates solid-color frames. Never connects a camera, microphone or screen capture. */
final class SyntheticMediaCheck {
 static void run(Context c,Bundle report)throws Exception{
  String id="test:synthetic-media",pref="camera_captures:"+id;String previous=DeviceStore.preference(c,pref,"[]");MediaCodec encoder=null;CameraRecording recording=null;
  try{
   Bitmap bitmap=Bitmap.createBitmap(64,64,Bitmap.Config.ARGB_8888);bitmap.eraseColor(Color.MAGENTA);CameraCaptures.picture(c,id,bitmap);bitmap.recycle();JSONArray captures=CameraCaptures.list(c,id);Uri picture=Uri.parse(captures.getJSONObject(0).getString("uri"));try(java.io.InputStream input=c.getContentResolver().openInputStream(picture)){Bitmap restored=BitmapFactory.decodeStream(input);if(restored==null||restored.getWidth()!=64||restored.getPixel(32,32)!=Color.MAGENTA)throw new Exception("PNG roundtrip failed");restored.recycle();}report.putBoolean("synthetic_png_roundtrip",true);
   for(String mime:new String[]{"video/avc","video/hevc"}){MediaFormat format=MediaFormat.createVideoFormat(mime,320,240);format.setInteger(MediaFormat.KEY_COLOR_FORMAT,MediaCodecInfo.CodecCapabilities.COLOR_FormatYUV420Flexible);format.setInteger(MediaFormat.KEY_BIT_RATE,64000);format.setInteger(MediaFormat.KEY_FRAME_RATE,10);format.setInteger(MediaFormat.KEY_I_FRAME_INTERVAL,1);encoder=MediaCodec.createEncoderByType(mime);encoder.configure(format,null,null,MediaCodec.CONFIGURE_FLAG_ENCODE);encoder.start();int queued=0,encoded=0;boolean ended=false;MediaCodec.BufferInfo info=new MediaCodec.BufferInfo();long deadline=android.os.SystemClock.elapsedRealtime()+10000;
   while(!ended&&android.os.SystemClock.elapsedRealtime()<deadline){if(queued<=12){int in=encoder.dequeueInputBuffer(10000);if(in>=0){ByteBuffer data=encoder.getInputBuffer(in);data.clear();if(queued==12)encoder.queueInputBuffer(in,0,0,queued*100000L,MediaCodec.BUFFER_FLAG_END_OF_STREAM);else{for(int x=0;x<115200;x++)data.put((byte)(x<76800?80+queued*4:128));encoder.queueInputBuffer(in,0,115200,queued*100000L,0);}queued++;}}int out=encoder.dequeueOutputBuffer(info,10000);if(out==MediaCodec.INFO_OUTPUT_FORMAT_CHANGED)recording=new CameraRecording(c,id,encoder.getOutputFormat());else if(out>=0){if(info.size>0&&(info.flags&MediaCodec.BUFFER_FLAG_CODEC_CONFIG)==0){ByteBuffer data=encoder.getOutputBuffer(out);data.position(info.offset);byte[] bytes=new byte[info.size];data.get(bytes);if(recording==null)throw new Exception("Missing muxer format");recording.accept("video/avc".equals(mime)?4:5,info.presentationTimeUs/1000,bytes);encoded++;}ended=(info.flags&MediaCodec.BUFFER_FLAG_END_OF_STREAM)!=0;encoder.releaseOutputBuffer(out,false);}}
   if(!ended||encoded<10||recording==null)throw new Exception("Synthetic encoding did not complete");recording.stop();recording=null;captures=CameraCaptures.list(c,id);Uri video=Uri.parse(captures.getJSONObject(0).getString("uri"));MediaExtractor extractor=new MediaExtractor();try{extractor.setDataSource(c,video,null);if(extractor.getTrackCount()!=1||!mime.equals(extractor.getTrackFormat(0).getString(MediaFormat.KEY_MIME)))throw new Exception("MP4 track invalid");extractor.selectTrack(0);int samples=0;ByteBuffer data=ByteBuffer.allocate(65536);while(extractor.readSampleData(data,0)>0){samples++;if(!extractor.advance())break;}if(samples<10)throw new Exception("MP4 samples missing");report.putInt("video/avc".equals(mime)?"synthetic_avc_samples":"synthetic_hevc_samples",samples);}finally{extractor.release();}encoder.stop();encoder.release();encoder=null;}report.putBoolean("synthetic_mp4_roundtrip",true);report.putBoolean("real_media_captured",false);
  }catch(Exception failure){report.putString("synthetic_error",failure.toString());report.putString("synthetic_trace",java.util.Arrays.toString(failure.getStackTrace()));throw failure;}finally{if(recording!=null)recording.abort();if(encoder!=null){try{encoder.stop();}catch(Exception ignored){}encoder.release();}JSONArray files=CameraCaptures.list(c,id);for(int i=0;i<files.length();i++){JSONObject item=files.optJSONObject(i);if(item!=null)try{c.getContentResolver().delete(Uri.parse(item.getString("uri")),null,null);}catch(Exception ignored){}}DeviceStore.putPreference(c,pref,previous);report.putBoolean("synthetic_files_removed",true);}
 }
}
